1	import { NextRequest, NextResponse } from "next/server";
2	import { resolveMailbox, withImap } from "@/lib/mail/imap";
3	
4	// GET /api/mail/attachment?folder=&uid=&part=&mailbox=
5	//
6	// Streams a single MIME part of one of the caller's own messages. Auth +
7	// ownership are enforced by `resolveMailbox` (requires a signed-in user and that
8	// the mailbox belongs to them); the IMAP server itself only exposes that user's
9	// messages, so there is no cross-account path here.
10	export async function GET(req: NextRequest) {
11	  const sp = req.nextUrl.searchParams;
12	  const folder = sp.get("folder")?.trim();
13	  const uidRaw = sp.get("uid")?.trim();
14	  // Attachment ids are "<uid>:<partId>". The UI sometimes passes the whole id as
15	  // `part` — accept that and use only the partId (the segment after the colon).
16	  const partRaw = sp.get("part")?.trim();
17	  const part = partRaw && partRaw.includes(":") ? partRaw.slice(partRaw.indexOf(":") + 1) : partRaw;
18	  const mailbox = sp.get("mailbox")?.trim() || undefined;
19	
20	  const uid = Number(uidRaw);
21	  if (!folder || !part || !uidRaw || !Number.isInteger(uid) || uid <= 0) {
22	    return NextResponse.json({ error: "bad request" }, { status: 400 });
23	  }
24	
25	  let cred;
26	  try {
27	    ({ cred } = await resolveMailbox(mailbox));
28	  } catch (e) {
29	    const msg = String((e as Error)?.message ?? e);
30	    const status = msg === "UNAUTHORIZED" ? 401 : 403;
31	    return NextResponse.json({ error: msg }, { status });
32	  }
33	
34	  try {
35	    const result = await withImap(cred, async (client) => {
36	      const lock = await client.getMailboxLock(folder, { readOnly: true });
37	      try {
38	        const many = await client.downloadMany(String(uid), [part], { uid: true });
39	        return many[part] ?? null;
40	      } finally {
41	        lock.release();
42	      }
43	    });
44	
45	    if (!result || !result.content) {
46	      return NextResponse.json({ error: "not found" }, { status: 404 });
47	    }
48	
49	    const contentType = result.meta?.contentType || "application/octet-stream";
50	    const filename = sanitizeFilename(result.meta?.filename) || `attachment-${part}`;
51	
52	    return new NextResponse(new Uint8Array(result.content), {
53	      status: 200,
54	      headers: {
55	        "Content-Type": contentType,
56	        "Content-Disposition": `attachment; filename="${filename}"; filename*=UTF-8''${encodeURIComponent(filename)}`,
57	        "Content-Length": String(result.content.length),
58	        "X-Content-Type-Options": "nosniff",
59	        "Cache-Control": "private, no-store",
60	      },
61	    });
62	  } catch (e) {
63	    return NextResponse.json({ error: String((e as Error)?.message ?? e).slice(0, 200) }, { status: 502 });
64	  }
65	}
66	
67	// Strip path separators, quotes and control chars so the filename can't break
68	// out of the Content-Disposition header.
69	function sanitizeFilename(name?: string): string {
70	  if (!name) return "";
71	  const cleaned = Array.from(name)
72	    .filter((ch) => {
73	      const c = ch.codePointAt(0) ?? 0;
74	      if (c < 0x20 || c === 0x7f) return false; // control chars
75	      if (ch === '"' || ch === "\\" || ch === "/") return false;
76	      return true;
77	    })
78	    .join("");
79	  return cleaned.trim().slice(0, 200);
80	}
