3	// Server actions for the native webmail "Mailbox settings" panel
4	// (components/customer/mail/MailSettings.tsx, opened from the FolderRail).
5	//
6	// Every action authenticates the caller and resolves ONLY a mailbox they own via
7	// `resolveMailbox` (which also performs the ownership check used everywhere else
8	// in the mail client). Writes are rate-limited and return a friendly
9	// `{ ok, error }`. Alias operations additionally verify the target domain is one
10	// the caller actually owns (an EmailSubscription) before touching Mailcow.
11	
12	import { db } from "@/lib/db";
13	import { checkRateLimit } from "@/lib/rate-limit";
14	import { resolveMailbox } from "@/lib/mail/imap";
15	import {
16	  mailcowConfigured,
17	  mcListAliases,
18	  mcAddAlias,
19	  mcDeleteAlias,
20	  type MailcowAlias,
21	} from "@/lib/mailcow";
22	import { resetMailboxPassword } from "@/lib/actions-email-hosting";
23	import { safeHtml } from "@/lib/mail/render";
24	import { signatureHtmlToText, SIGNATURE_HTML_MAX } from "@/lib/mail/signature";
25	
26	export type Result = { ok: boolean; error?: string };
27	
28	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
29	
30	/** Serialisable mailbox settings the panel reads/writes. */
31	export type MailboxSettings = {
32	  address: string;
33	  domain: string;
34	  displayName: string;
35	  // Identity
36	  replyTo: string;
37	  organization: string;
38	  // Signature
39	  signature: string; // derived / legacy plain-text
40	  signatureHtml: string; // sanitized rich HTML (source of truth)
41	  signatureEnabled: boolean;
42	  signatureOnReply: boolean;
43	  signaturePlacement: "above" | "below";
44	  // Auto-reply
45	  autoReplyEnabled: boolean;
46	  autoReplySubject: string;
47	  autoReplyBody: string;
48	  autoReplyStart: string; // "YYYY-MM-DD" or ""
49	  autoReplyEnd: string; // "YYYY-MM-DD" or ""
50	  // Forwarding (stored)
51	  forwardingAddress: string;
52	  forwardKeepCopy: boolean;
53	  // Storage
54	  quotaMB: number | null;
55	};
56	
57	function domainOf(address: string): string {
58	  const at = address.lastIndexOf("@");
59	  return at >= 0 ? address.slice(at + 1).toLowerCase() : "";
60	}
61	
62	/** Format a stored Date as a `YYYY-MM-DD` string (or "" when null). */
63	function toDateInput(d: Date | null | undefined): string {
64	  if (!d) return "";
65	  try {
66	    return d.toISOString().slice(0, 10);
67	  } catch {
68	    return "";
69	  }
70	}
71	
72	/** Parse a `YYYY-MM-DD` string into a UTC Date, or null when blank/invalid. */
73	function fromDateInput(s: string | null | undefined): Date | null {
74	  const v = (s ?? "").trim();
75	  if (!v) return null;
76	  const d = new Date(`${v}T00:00:00.000Z`);
77	  return Number.isNaN(d.getTime()) ? null : d;
78	}
79	
80	/** Rate-limit gate returning a friendly `{ ok:false }` instead of throwing. */
81	function gate(key: string, max: number, windowMs: number): Result | null {
82	  const r = checkRateLimit(key, { max, windowMs });
83	  if (!r.ok) return { ok: false, error: `Too many requests — wait ${r.retryAfterSec}s and try again.` };
84	  return null;
85	}
