87	/** The domains the signed-in user owns (from their email subscriptions). */
88	async function ownedDomains(userId: string): Promise<Set<string>> {
89	  const subs = await db.emailSubscription.findMany({
90	    where: { userId },
91	    select: { domainName: true },
92	  });
93	  return new Set(subs.map((s) => s.domainName.trim().toLowerCase()).filter(Boolean));
94	}
