294	/** List the aliases on the mailbox's domain. */
295	export async function listAliases(
296	  mailboxAddress?: string,
297	): Promise<{ ok: boolean; error?: string; aliases: AliasRow[] }> {
298	  const { user, address } = await resolveMailbox(mailboxAddress);
299	  const domain = domainOf(address);
300	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet.", aliases: [] };
301	
302	  const owned = await ownedDomains(user.id);
303	  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain.", aliases: [] };
304	
305	  try {
306	    const list = await mcListAliases(domain);
307	    return { ok: true, aliases: toAliasRows(list) };
308	  } catch (e) {
309	    return { ok: false, error: friendly(e), aliases: [] };
310	  }
311	}
