277	/** Escape a value for safe interpolation into a double-quoted HTML attribute. */
278	function escAttr(v: string): string {
279	  return v
280	    .replace(/&/g, "&amp;")
281	    .replace(/"/g, "&quot;")
282	    .replace(/</g, "&lt;")
283	    .replace(/>/g, "&gt;");
284	}
285	
286	/** Clamp a signature-image width to a sane px range so it never breaks the email layout. */
287	function clampImgWidth(n: number): number {
288	  return Math.min(1000, Math.max(40, Math.round(n)));
289	}
290	
291	/** Escape plain text into HTML for the legacy-plain -> HTML seeding path. */
292	function plainToHtml(plain: string): string {
293	  const esc = plain.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
294	  return `<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;color:#334155">${esc.replace(/\n/g, "<br>")}</div>`;
295	}
