/**
 * Fetch the DKIM public-key TXT value for a domain from Mailcow
 * (`GET /api/v1/get/dkim/<domain>`). Mailcow returns an object carrying the
 * ready-to-publish TXT in `dkim_txt` (selector `dkim`). Returns the TXT string,
 * or null when the domain has no DKIM key yet or the shape is unexpected.
 *
 * Throws MailcowError only when the integration is unreachable/errors — callers
 * that must stay tolerant wrap this in try/catch.
 */
export async function mcGetDkim(domain: string): Promise<string | null> {
  const res = await mcRequest("GET", `/get/dkim/${encodeURIComponent(domain)}`);
  if (!res || typeof res !== "object") return null;
  // Mailcow returns {} for a domain with no key configured.
  const txt = (res as { dkim_txt?: unknown }).dkim_txt;
  if (typeof txt === "string" && txt.trim()) return txt.trim();
  return null;
}

// ---------- Analytics ----------

export type MailStats = {
  configured: true;
  domains: number;
  mailboxes: number;
  postfix: {
    sampled: number;
    sent: number;
    deferred: number;
    bounced: number;
    rejected: number;
    other: number;
  };
  rspamd: {
    sampled: number;
    actions: Record<string, number>;
    spam: number; // reject + add header + rewrite subject
    clean: number; // no action + greylist / soft reject
  };
};

function asArray(v: unknown): unknown[] {
  if (Array.isArray(v)) return v;
  if (v && typeof v === "object" && Array.isArray((v as { rows?: unknown[] }).rows)) {
    return (v as { rows: unknown[] }).rows;
  }
  return [];
}

/**
 * Pull recent postfix + rspamd logs and domain/mailbox counts for the admin
 * deliverability view. Throws (MailcowError) if not configured or unreachable —
 * the admin page catches that and shows a graceful fallback.
 */
export async function mcStats(sample = 400): Promise<MailStats> {
  config(); // throws early with a clear message if not configured

  const [domainsRaw, mailboxesRaw, postfixRaw, rspamdRaw] = await Promise.all([
    mcRequest("GET", "/get/domain/all").catch(() => []),
    mcRequest("GET", "/get/mailbox/all").catch(() => []),
    mcRequest("GET", `/get/logs/postfix/${sample}`).catch(() => []),
    mcRequest("GET", `/get/logs/rspamd-history/${sample}`).catch(() => []),
  ]);

  const postfixLogs = asArray(postfixRaw);
  const postfix = { sampled: postfixLogs.length, sent: 0, deferred: 0, bounced: 0, rejected: 0, other: 0 };
  for (const entry of postfixLogs) {
    const msg = String(
      (entry as { message?: unknown })?.message ??
        (entry && typeof entry === "object" ? JSON.stringify(entry) : entry) ??
        "",
    ).toLowerCase();
    if (msg.includes("status=sent")) postfix.sent++;
    else if (msg.includes("status=deferred")) postfix.deferred++;
    else if (msg.includes("status=bounced")) postfix.bounced++;
    else if (msg.includes("reject:") || msg.includes("status=reject")) postfix.rejected++;
    else postfix.other++;
  }

  const rspamdLogs = asArray(rspamdRaw);
  const actions: Record<string, number> = {};
  let spam = 0;
  let clean = 0;
  for (const entry of rspamdLogs) {
    const action = String((entry as { action?: unknown })?.action ?? "unknown").toLowerCase();
    actions[action] = (actions[action] ?? 0) + 1;
    if (action === "reject" || action === "add header" || action === "rewrite subject") spam++;
    else clean++;
  }

  return {
    configured: true,
    domains: asArray(domainsRaw).length,
    mailboxes: asArray(mailboxesRaw).length,
    postfix,
    rspamd: { sampled: rspamdLogs.length, actions, spam, clean },
  };
}

