import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { validateImageBytes, MAX_ATTACHMENT_BYTES } from "@/lib/chat-attachment";
import { appUrl } from "@/lib/email-render";

export const runtime = "nodejs";

/**
 * Image upload for the webmail SIGNATURE editor.
 *
 * POST /api/mail/signature-image  (multipart/form-data: file) — the signed-in
 * mailbox owner picks an image from their computer; we validate its real bytes
 * (signature sniff rejects SVG/non-images, cap 5 MB), store the bytes in
 * Postgres under the user's id, and return an ABSOLUTE https URL:
 *
 *   { url: "https://nxeon.cloud/api/mail/signature-image/<cuid>" }
 *
 * The editor inserts that URL as an <img src>. It is absolute (not a relative
 * "/api/…" path) so the image also loads in the RECIPIENT'S external mail
 * client, which has no notion of our origin. We host rather than inline because
 * `safeHtml` strips `data:` URLs and email clients block inline data images.
 *
 * Only authenticated owners may upload (requireUser). Per-user + per-IP rate
 * limited. To keep storage bounded we cap the number of images per user and
 * prune the oldest when over the cap.
 */

const MAX_IMAGES_PER_USER = 20;

function clientIp(req: Request): string {
  const xff = req.headers.get("x-forwarded-for") ?? "";
  const first = xff.split(",")[0]?.trim();
  return first || "unknown";
}

export async function POST(req: Request) {
  let user;
  try {
    user = await requireUser();
  } catch {
    return NextResponse.json({ error: "You must be signed in to upload an image." }, { status: 401 });
  }

  const rl = checkRateLimit(`sig-image:${user.id}:${clientIp(req)}`, { max: 15, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "Too many uploads. Please slow down." },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } },
    );
  }

  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "Invalid upload." }, { status: 400 });
  }

  const file = form.get("file");
  if (!(file instanceof File)) {
    return NextResponse.json({ error: "No image provided." }, { status: 400 });
  }
  // Cheap guard before buffering the whole body into memory.
  if (file.size > MAX_ATTACHMENT_BYTES) {
    return NextResponse.json({ error: "Image is larger than 5 MB." }, { status: 413 });
  }

  const bytes = Buffer.from(await file.arrayBuffer());
  const check = validateImageBytes(bytes, file.type);
  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });

  const created = await db.signatureImage.create({
    data: {
      userId: user.id,
      mime: check.mime,
      sizeBytes: check.bytes.length,
      data: new Uint8Array(check.bytes),
    },
    select: { id: true },
  });

  // Keep storage bounded: prune the user's oldest images beyond the cap.
  try {
    const old = await db.signatureImage.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      skip: MAX_IMAGES_PER_USER,
      select: { id: true },
    });
    if (old.length > 0) {
      await db.signatureImage.deleteMany({ where: { id: { in: old.map((r) => r.id) } } });
    }
  } catch {
    /* pruning is best-effort — never fail the upload over it */
  }

  return NextResponse.json({ url: `${appUrl()}/api/mail/signature-image/${created.id}` });
}
